using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CoastalRequestsVerify{static CoastalRequestsVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoastalRequestsVerify.request"))return;File.Delete("CoastalRequestsVerify.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CoastalRequestsVerify.txt",e.ToString());}}
static Vector2 Nearest(Vector3 p,List<Vector2> l){float best=float.MaxValue;Vector2 n=Vector2.zero;for(int i=1;i<l.Count;i++){var e=l[i]-l[i-1];float t=Mathf.Clamp01(Vector2.Dot(new Vector2(p.x,p.z)-l[i-1],e)/e.sqrMagnitude);float d=(new Vector2(p.x,p.z)-l[i-1]-t*e).sqrMagnitude;if(d<best){best=d;n=new Vector2(e.y,-e.x).normalized;}}return n;}static void Run(){var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var outer=s.GetRootGameObjects().Single(g=>g.name=="South Coast Beach Details");var canal=s.GetRootGameObjects().Single(g=>g.name=="Canal Bank Beach Details");var roofs=s.GetRootGameObjects().Single(g=>g.name=="City 15 Rooftop Helipads");var cliffs=s.GetRootGameObjects().Single(g=>g.name=="Offshore Cliff Lighthouse Landmarks");var north=new List<Vector2>{new Vector2(117.3f,575),new Vector2(117.3f,350),new Vector2(114.23f,0),new Vector2(114.23f,-350),new Vector2(122.72f,-401.25f),new Vector2(139.55f,-426.81f),new Vector2(159.39f,-447.31f),new Vector2(180.58f,-463.61f),new Vector2(220.87f,-482.45f),new Vector2(283.08f,-492.45f),new Vector2(410.9f,-493.91f),new Vector2(660,-494)};var hull=File.ReadAllLines("FinalEnvironmentRoadReview/BeachSouthHull.csv").Select(v=>{var a=v.Split(',');return new Vector2(float.Parse(a[0],System.Globalization.CultureInfo.InvariantCulture),float.Parse(a[1],System.Globalization.CultureInfo.InvariantCulture));}).ToList();int start=hull.FindIndex(v=>v.x<0&&v.y>590);var coast=new List<Vector2>{new Vector2(0,596.75f)};for(int i=start;i<hull.Count;i++)coast.Add(hull[i]);for(int i=0;i<start&&hull[i].x<0;i++)coast.Add(hull[i]);coast.Add(new Vector2(0,-783.12f));int facing=0,groups=0;foreach(var root in new[]{outer,canal})foreach(var l in root.GetComponentsInChildren<LODGroup>().Where(l=>l.name.Contains("Colorful"))){var p=l.transform.position;var n=root==outer?Nearest(p,coast):p.x<50?Vector2.right:Nearest(p,north);if(Vector3.Dot(-l.transform.forward,new Vector3(n.x,0,n.y))<.99f)facing++;groups++;}var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/YachtPortAtlas/Shared Yacht Yard Atlas.mat");int roofOther=roofs.GetComponentsInChildren<MeshRenderer>().Count(r=>r.sharedMaterial!=mat);var newMats=new[]{outer,canal,roofs,cliffs}.SelectMany(r=>r.GetComponentsInChildren<Renderer>()).SelectMany(r=>r.sharedMaterials).Distinct().ToArray();int errors=newMats.Sum(m=>ShaderUtil.GetShaderMessages(m.shader).Count(e=>e.severity.ToString()=="Error"));var roads=s.GetRootGameObjects().Single(g=>g.name=="Track Roads");var yard=roads.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var buffer=yard.GetComponent<Renderer>().bounds;buffer.Expand(new Vector3(35,40,35));int overlaps=new[]{outer,canal}.SelectMany(r=>r.GetComponentsInChildren<LODGroup>()).Count(l=>buffer.Contains(l.transform.position));int gapRoots=roads.GetComponentsInChildren<MeshFilter>().Count(f=>f.name.ToLower().Contains("beach promenade sidewalk joins"));var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);var shore=roads.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Outer_MEsh");cap.Invoke(null,new object[]{s,new Vector3(-580,40,70),new Vector3(-500,27,70),"Soft-Sand-Promenade-Join"});cap.Invoke(null,new object[]{s,new Vector3(290,850,-100),new Vector3(290,25,-100),"Canal-Beach-Details-Overview"});File.WriteAllText("FinalEnvironmentRoadReview/CoastalRequestsVerify.txt","SUCCESS roof signs="+roofs.transform.childCount+" same-atlas violations="+roofOther+"; offshore cliff/lighthouse prefabs="+cliffs.transform.childCount+"; total seating groups="+groups+" chairs="+groups*2+" wrong water-facing groups="+facing+"; port buffer overlaps="+overlaps+"; paving join root count="+gapRoots+"; shader errors="+errors+". All new textures reuse existing atlases/materials; scene and all master prefabs saved.");}}

